import{_ as o,l as r,o as e,c as s,v as t,p as n,x as i,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"模型残差分析","description":"","frontmatter":{"title":"模型残差分析","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/model-residual-analysis.md","filePath":"litho/model-residual-analysis.md","lastUpdated":1789023840000}'),p={name:"litho/model-residual-analysis.md"};function A(c,a,u,_,m,P){const l=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="模型残差分析" tabindex="-1">模型残差分析 <a class="header-anchor" href="#模型残差分析" aria-label="Permalink to &quot;模型残差分析&quot;">​</a></h1><div class="epigraph"><p>RMSE 一个数会把「光学核半径错了」和「二维没见过」平均掉；残差要按节距、取向和邻域切开看。</p><footer>—— 对照 OPC 模型残差诊断与通过节距误差指纹的产线通称</footer></div><p><a href="/litho/test-patterns-gauges">上一课</a>给出有结构的测量。缺口是拟合结束后如何决定：加项、改光学、还是承认某类图形不进 OPC 而进设计规则禁止。本课钉残差分析。轮廓从 2D 边升级到 3D 胶形，留给[下一课](/litho/3d-resist-model）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>总 RMSE 合格时，某一节距族仍可有纳米级系统偏，正好落在产品金属节距上。残差分析把误差对通过节距、密度、方位、线端、孔、剂量、焦点作图。正弦状通过节距残差常指向 TCC/光学半径；焦点不对称指向 3D 或像差；只在二维爆指向 gauge 缺失或紧凑模型阶次不够。</p><p>缺口是<strong>诊断</strong>，不是再跑一次最小二乘。把残差当随机噪声去加 ML 修正，会在未抽样处编造假安全。</p><h3 id="空间相关不是更多胶项的许可证" tabindex="-1">空间相关不是更多胶项的许可证 <a class="header-anchor" href="#空间相关不是更多胶项的许可证" aria-label="Permalink to &quot;空间相关不是更多胶项的许可证&quot;">​</a></h3><p>相邻 gauge 残差相关，说明缺的是平滑的物理核，不是再加一个局域经验项。经验项会在产品上以另一种相关出现。</p><p><span class="marginnote">残差必须分 ADI/AEI。刻蚀负载的残差不该用胶项去背，否则换腔体时「胶模型」一起漂。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>图：residual vs pitch、vs isolation、Bossung 残差、向量 EPE 图（二维）。统计：按层、按扫描机、按掩模。行动：超光学规格 → 回严格 EMF 或照明文件；超胶规格 → 改模糊/阈值；超刻蚀 → 进刻蚀核；某族无药 → 禁止或改 SMO/规则。</p><p>与热点：残差图上的族应与 LRC 热点清单重叠；不重叠则计量与仿真不在同一轮廓定义上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>前向模型是光滑算子，系统残差也光滑，除非计量跳变（SEM 配方边界）。因此「棋盘噪声」更像计量，不该进光学核。EUV 随机会在重复测量的方差里，不该进均值模型残差的偏差项——要拆 bias/variance。</p>',14)),(e(),n(h,null,{default:i(()=>[E(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20RES%5B%22%E6%AE%8B%E5%B7%AE%E5%BC%A0%E9%87%8F%22%5D%20--%3E%20PIT%5B%22%E5%AF%B9%E8%8A%82%E8%B7%9D%20%2F%20%E5%AF%86%E5%BA%A6%22%5D%0A%20%20RES%20--%3E%20DIM%5B%22%E5%AF%B9%201D%20vs%202D%22%5D%0A%20%20RES%20--%3E%20PW%5B%22%E5%AF%B9%E5%89%82%E9%87%8F%E7%84%A6%E7%82%B9%22%5D%0A%20%20PIT%20--%3E%20ACT%5B%22%E6%94%B9%E5%85%89%E5%AD%A6%20%2F%20%E8%83%B6%20%2F%20%E8%A7%84%E5%88%99%22%5D%0A%20%20DIM%20--%3E%20ACT%0A%20%20PW%20--%3E%20ACT%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分析不自动修复。保持集很小时代入产品是赌博。不把某次 TAPOUT 的残差表当作物理常数。</p><p>后课默认：2D 轮廓残差已被切开诊断；下一课问胶还有厚度方向的形——侧壁与顶损失——2D EPE 是否够签核。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>残差按节距、维度、窗口切开，才能决定改哪一层模型。</li><li>相关残差指向缺核，不指向无限加经验项。</li><li>ADI/AEI、bias/variance（随机）要拆。</li><li>出处：OPC 模型残差诊断产线通称。</li></ul>',5))])}const f=o(p,[["render",A]]);export{D as __pageData,f as default};
